def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out

    rmin = min(r for r, c in fours)
    rmax = max(r for r, c in fours)
    cmin = min(c for r, c in fours)
    cmax = max(c for r, c in fours)

    srmin = min(r for r, c in sixes)
    srmax = max(r for r, c in sixes)
    scmin = min(c for r, c in sixes)
    scmax = max(c for r, c in sixes)

    for r, c in sixes:
        out[r][c] = 0

    # The marker's silhouette indicates the reflection direction.
    marker_rows = {
        r: {c for rr, c in sixes if rr == r}
        for r in range(srmin, srmax + 1)
    }
    marker_cols = {
        c: {r for r, cc in sixes if cc == c}
        for c in range(scmin, scmax + 1)
    }

    if len(marker_rows[srmin]) > 1 and len(marker_rows[srmax]) == 1:
        # T with its bar at the top: reflect to the right.
        mode = "right"
    elif len(marker_rows[srmax]) > 1 and len(marker_rows[srmin]) == 1:
        # T with its bar at the bottom: reflect to the left.
        mode = "left"
    else:
        # Cross-like marker: the longer horizontal arm determines up/down.
        midrow = (srmin + srmax) // 2
        bar = marker_rows[midrow]
        spine = max(marker_cols, key=lambda c: len(marker_cols[c]))
        left_arm = spine - min(bar)
        right_arm = max(bar) - spine
        mode = "down" if left_arm > right_arm else "up"

    for r, c in fours:
        if mode == "down":
            nr, nc = 2 * rmax + 1 - r, c
        elif mode == "up":
            nr, nc = 2 * rmin - 1 - r, c
        elif mode == "right":
            nr, nc = r, 2 * cmax + 1 - c
        else:
            nr, nc = r, 2 * cmin - 1 - c
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = 4

    return out
